package estate.svc;

import org.junit.jupiter.api.Test;

import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class MainTest {
    private Main start(FakeContext c) throws Exception {
        Main m = new Main();
        m.start(c);
        return m;
    }

    @Test
    void postStoresAndPublishes() throws Exception {
        FakeContext c = new FakeContext();
        Main m = start(c);
        Map<String, String> r = m.handle("post", Map.of("account", "a1", "amount", "12.5", "requestId", "r1"));
        assertEquals("false", r.get("dup"));
        Map<String, String> balance = m.handle("balance", Map.of("account", "a1"));
        assertEquals("12.50", balance.get("balance"));
        assertEquals("1250", balance.get("balanceCents"));
        assertEquals("payment.posted", c.published.get(0));
        assertEquals("12.50", c.events.get(0).get("amount"));

        try (var rs = c.db().createStatement().executeQuery("SELECT amount_cents FROM postings")) {
            assertTrue(rs.next());
            assertEquals(1250L, rs.getLong(1));
        }
    }

    @Test
    void sameRequestIdPostsOnce() throws Exception {
        FakeContext c = new FakeContext();
        Main m = start(c);
        m.handle("post", Map.of("account", "a1", "amount", "5.00", "requestId", "r1"));
        Map<String, String> r = m.handle("post", Map.of("account", "a1", "amount", "5.00", "requestId", "r1"));
        assertEquals("true", r.get("dup"));
        assertEquals("1", m.handle("postings", Map.of("account", "a1")).get("count"));
        assertEquals(1, c.events.size());
    }

    @Test
    void healthIsUp() throws Exception {
        assertEquals("UP", start(new FakeContext()).handle("health", Map.of()).get("status"));
    }

    @Test
    void migratesExistingPostingsToCents() throws Exception {
        FakeContext c = new FakeContext();
        try (var s = c.db().createStatement()) {
            s.execute("CREATE TABLE schema_version(v INT NOT NULL)");
            s.execute("INSERT INTO schema_version(v) VALUES (1)");
            s.execute("CREATE TABLE postings(id BIGINT AUTO_INCREMENT PRIMARY KEY, account VARCHAR(40) NOT NULL, "
                    + "amount DECIMAL(18,2) NOT NULL, request_id VARCHAR(80) NOT NULL UNIQUE, ts BIGINT NOT NULL)");
            s.execute("INSERT INTO postings(account, amount, request_id, ts) VALUES ('a1', 7.25, 'old', 1)");
        }

        Main m = start(c);

        Map<String, String> balance = m.handle("balance", Map.of("account", "a1"));
        assertEquals("7.25", balance.get("balance"));
        assertEquals("725", balance.get("balanceCents"));
        try (var rs = c.db().createStatement().executeQuery("SELECT v FROM schema_version ORDER BY v")) {
            assertTrue(rs.next());
            assertEquals(1, rs.getInt(1));
            assertTrue(rs.next());
            assertEquals(2, rs.getInt(1));
        }
    }
}
